// The two conjugate factors 1+i and 1-i with their moduli.
// size(W,H) bounds the output under Asymptote's default keepAspect and does not scale labels,
// so the compiled box is a measurement rather than the declaration. The values below are what
// asy 2.87 actually produced; re-measure with `npm run content:figures --
// --record-aspect-ratios` if the toolchain changes.
size(253,301);
usepackage("amsmath");
pair O=(0,0);
draw((-1.6,0)--(3.6,0),Arrow);
draw((0,-3.6)--(0,3.6),Arrow);
label("$\operatorname{Re}$",(3.7,0),E);
label("$\operatorname{Im}$",(0,3.7),N);
label("$1$",(1,0),S);
label("$1$",(0,1),E);
draw(O--(1,1));
draw(O--(1,-1));
dot((1,1), black+2.5pt);
dot((1,-1), black+2.5pt);
label("$1+i$",(1.2,1.2),NW);
label("$1-i$",(1.2,-1.2),SW);
label("equal moduli, conjugate positions",(2.6,2.8),N);

// The ellipse |z-1| + |z+1| = 6 with its foci marked on the real axis.
// size(W,H) bounds the output under Asymptote's default keepAspect and does not scale labels,
// so the compiled box is a measurement rather than the declaration. The values below are what
// asy 2.87 actually produced; re-measure with `npm run content:figures --
// --record-aspect-ratios` if the toolchain changes.
import graph;
size(321,271);
usepackage("amsmath");
draw(ellipse((0,0),3,2*sqrt(2)));
draw((-3.6,0)--(3.6,0),Arrow);
label("$\operatorname{Re}$",(3.7,0),E);
dot((1,0), black+2.5pt);
dot((-1,0), black+2.5pt);
label("focus $(1,0)$",(1,0.35),N);
label("focus $(-1,0)$",(-1,0.35),N);
label("sum of distances fixed at $6$",(0,-3.4),S);
